import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"伪文件系统","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/linux/file/pfs.md","filePath":"kernel/linux/file/pfs.md"}`),a={name:`kernel/linux/file/pfs.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="伪文件系统" tabindex="-1">伪文件系统 <a class="header-anchor" href="#伪文件系统" aria-label="Permalink to “伪文件系统”">​</a></h1><p>伪文件系统（Pseudo Filesystems）是 Linux 虚拟文件子系统（VFS）中的一类特殊文件系统，不依赖物理存储设备，而是由内核动态生成，用于暴露内核数据结构、设备信息或系统状态给用户态。它们通过 VFS 提供文件接口，遵循“一切皆文件”的哲学，方便用户和程序访问内核信息。</p><p>文件和目录内容实时反映内核状态，运行时创建；部分伪文件系统（如 <code>/proc</code>）只读，部分（如 <code>/sys</code>）支持写操作以配置内核。</p><h2 id="常见伪文件" tabindex="-1">常见伪文件 <a class="header-anchor" href="#常见伪文件" aria-label="Permalink to “常见伪文件”">​</a></h2><ol><li><p>/proc（procfs）</p><ul><li>作用：提供进程和内核信息的接口，反映系统状态。</li><li>内容： <ul><li>进程信息：如 <code>/proc/[pid]/status</code>（进程状态）、<code>/proc/[pid]/maps</code>（内存映射）。</li><li>系统信息：如 <code>/proc/cpuinfo</code>（CPU 信息）、<code>/proc/meminfo</code>（内存使用）。</li><li>内核参数：如 <code>/proc/sys/kernel/</code>（可读写配置，如 <code>sysctl</code>）。</li></ul></li><li>实现： <ul><li>注册为 <code>proc_fs_type</code>，使用 <code>proc_dir_entry</code> 管理文件和目录。</li><li>通过 <code>proc_ops</code>（类似 <code>file_operations</code>）实现文件操作。</li></ul></li><li>示例：<code>cat /proc/uptime</code> 查看系统运行时间。</li></ul></li><li><p>/sys（sysfs）</p><ul><li>作用：暴露设备、驱动和内核对象的属性，支持设备管理和配置。</li><li>内容： <ul><li>设备拓扑：<code>/sys/devices/</code> 反映硬件层级。</li><li>设备类型：<code>/sys/class/</code>（如网卡 <code>/sys/class/net/</code>）。</li><li>驱动信息：<code>/sys/bus/</code>（如 PCI、USB 设备）。</li></ul></li><li>实现： <ul><li>基于 <code>struct kobject</code>，通过 <code>sysfs_ops</code> 提供读写接口。</li><li>设备驱动通过 <code>kobject</code> 创建 sysfs 条目，映射到文件。</li></ul></li><li>示例：<code>echo 1 &gt; /sys/class/leds/brightness</code> 控制 LED。</li></ul></li><li><p>/dev（devfs 或 udev）</p><ul><li>作用：提供设备文件接口，表示字符设备和块设备。</li><li>内容： <ul><li>字符设备（如 <code>/dev/tty</code>）、块设备（如 <code>/dev/sda</code>）。</li><li>动态管理：由 <code>udev</code>（用户态）或内核动态创建设备文件。</li></ul></li><li>实现： <ul><li>传统 devfs 已废弃，现由 <code>udev</code> 配合 tmpfs 实现。udev 是一个用户态的服务程序，通过监听内核的 uevent 硬件事件，特别是设备的插拔事件，从而来动态为 /dev 目录创建设备的虚拟文件，提供设备的访问接口。其他的伪文件系统是由内核实现的，而 /dev 伪文件由用户态的 udev 服务配合实现，这一点区别于其他的伪文件系统。</li><li>设备驱动通过 <code>register_chrdev</code> 或 <code>cdev_add</code> 注册，VFS 创建 <code>inode</code>（含 <code>i_cdev</code> 或 <code>i_bdev</code>）。</li></ul></li><li>示例：<code>cat /dev/random</code> 获取随机数。</li></ul></li><li><p>/tmpfs（tmpfs）</p><ul><li>作用：基于内存的文件系统，数据存储在 RAM，速度快，断电丢失。</li><li>内容：常用于临时文件或共享内存（如 <code>/dev/shm</code>）。</li><li>实现： <ul><li>注册为 <code>tmpfs_fs_type</code>，数据存储在页面缓存，无需块设备。</li><li>支持 <code>file_operations</code> 和 <code>inode_operations</code>。</li></ul></li><li>示例：<code>mount -t tmpfs tmpfs /mnt</code> 创建内存文件系统。</li></ul></li><li><p>/debug（debugfs）</p><ul><li>作用：提供内核开发者调试接口，暴露内部数据结构。</li><li>内容：自定义调试信息，由驱动或子系统注册（如 <code>/debug/tracing</code>）。</li><li>实现： <ul><li>注册为 <code>debugfs_fs_type</code>，通过 <code>debugfs_create_file</code> 创建文件。</li><li>提供简单接口（如 <code>debugfs_create_u32</code>）添加调试节点。</li></ul></li><li>示例：<code>cat /debug/tracing/trace</code> 查看内核跟踪日志。</li></ul></li></ol><h3 id="伪文件系统的工作原理" tabindex="-1">伪文件系统的工作原理 <a class="header-anchor" href="#伪文件系统的工作原理" aria-label="Permalink to “伪文件系统的工作原理”">​</a></h3><p>伪文件系统首先通过 <code>register_filesystem</code> 向内核注册自己的 <code>struct file_system_type</code>（如 <code>proc_fs_type</code>），并在挂载时（如 <code>mount -t proc proc /proc</code>）由 VFS 创建对应的 <code>struct super_block</code>。伪文件和目录在内核中由 <code>struct inode</code> 和 <code>struct dentry</code> 结构体表示，并绑定特定的操作函数（如 <code>proc_ops</code> 或 <code>sysfs_ops</code>），实现与 VFS 的集成。</p><p>与传统文件系统不同，伪文件系统的文件内容并不存储在磁盘上，而是由内核在访问时动态生成。每个文件的 <code>read</code> 或 <code>write</code> 回调函数会实时从内核数据结构中获取或更新信息，例如 <code>/proc/cpuinfo</code> 的 <code>read</code> 操作会读取当前 CPU 的相关信息。</p><p>用户通过常规的文件操作命令（如 <code>cat</code>、<code>echo</code>）访问这些伪文件，VFS 会调用伪文件系统实现的 <code>file_operations</code>。对于支持写操作的伪文件（如 <code>/sys</code>），写入会触发内核回调，从而实现对设备或内核参数的动态配置和管理。</p><h2 id="procfs-的编程接口" tabindex="-1">procfs 的编程接口 <a class="header-anchor" href="#procfs-的编程接口" aria-label="Permalink to “procfs 的编程接口”">​</a></h2><p>内核子系统或驱动向 <code>/proc</code> 暴露信息的路径是 <code>proc_create</code>——它创建一个 <code>proc_dir_entry</code> 并注册 <code>proc_ops</code>（read/write 回调）：</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> my_proc_show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> seq_file </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    seq_printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;counter: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, my_counter);</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> __init </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my_init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    proc_create_single</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, my_proc_show);</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>proc_create_single</code> 是简单只读文件的现代封装（内部用 seq_file——内核的序列化输出缓冲，解决&quot;read 回调被多次调用、每次只填一页&quot;的拼接问题）。复杂场景直接用 <code>proc_create</code> 注册完整的 <code>proc_ops</code>，支持 read/write/llseek。老代码中的 <code>create_proc_entry</code> 已废弃——没有类型安全且容易出错。</p><p>proc 条目按目录组织（<code>proc_mkdir</code> 创建目录），子系统各有自己的命名空间：<code>/proc/sys/</code>（sysctl 参数）、<code>/proc/net/</code>（网络状态）、<code>/proc/&lt;pid&gt;/</code>（每进程信息，由内核动态生成）。<code>/proc/&lt;pid&gt;/</code> 下的条目不经过 proc_create——它们由进程子系统的固定表生成（<code>pid_entry</code> 数组），内容直接从 <code>task_struct</code> 读取。</p><p><strong>procfs 与 sysfs 的分工</strong>：procfs 暴露&quot;进程和内核状态&quot;（面向运维和诊断），sysfs 暴露&quot;设备模型&quot;（面向设备管理）。历史遗留使 <code>/proc/cpuinfo</code>、<code>/proc/interrupts</code> 这类硬件信息留在 procfs，但新代码的规则明确——设备属性进 sysfs，进程/内核状态进 procfs，调试信息进 debugfs。</p><h2 id="proc-目录的瞬时快照" tabindex="-1">/proc 目录的瞬时快照 <a class="header-anchor" href="#proc-目录的瞬时快照" aria-label="Permalink to “/proc 目录的瞬时快照”">​</a></h2><p><code>/proc</code> 常被称为&quot;系统状态的瞬时快照&quot;——每次读取都是当下时刻的实时值。常用条目速查：</p><table tabindex="0"><thead><tr><th>条目</th><th>内容</th><th>典型用途</th></tr></thead><tbody><tr><td><code>/proc/cpuinfo</code></td><td>CPU 型号、频率、flags</td><td>确认 CPU 特性（如 avx512、smx）</td></tr><tr><td><code>/proc/meminfo</code></td><td>内存分区使用详情</td><td>排查内存去向（Cached/Slab/Swap）</td></tr><tr><td><code>/proc/loadavg</code></td><td>1/5/15 分钟负载 + 运行队列</td><td>快速判断系统繁忙度</td></tr><tr><td><code>/proc/interrupts</code></td><td>每个 CPU 的中断计数</td><td>中断分布是否均衡（IRQ 亲和排查）</td></tr><tr><td><code>/proc/vmstat</code></td><td>内核内存管理事件计数</td><td>页回收/swap 活动分析</td></tr><tr><td><code>/proc/&lt;pid&gt;/status</code></td><td>进程状态摘要</td><td>查看 VMSize/RSS/线程数/上下文切换</td></tr><tr><td><code>/proc/&lt;pid&gt;/maps</code></td><td>内存映射区域</td><td>排查 so 库加载、内存布局</td></tr><tr><td><code>/proc/&lt;pid&gt;/sched</code></td><td>调度器统计</td><td>自愿/非自愿上下文切换、等待时间</td></tr><tr><td><code>/proc/&lt;pid&gt;/fd/</code></td><td>打开的文件描述符符号链接</td><td>&quot;这个进程打开了什么文件&quot;</td></tr><tr><td><code>/proc/&lt;pid&gt;/cmdline</code></td><td>启动命令行</td><td>参数用 \\0 分隔（<code>tr &#39;\\0&#39; &#39; &#39;</code> 查看）</td></tr><tr><td><code>/proc/sys/*</code></td><td>sysctl 可写参数</td><td><code>echo</code> 或 <code>sysctl</code> 运行时调参</td></tr></tbody></table><p>注意 read 语义的坑：多数 <code>/proc</code> 条目每次 read 返回&quot;当下的快照&quot;，但 <code>seq_file</code> 的多页拼接（如 <code>cat /proc/interrupts</code> 在长输出时）可能读到前后不一致的拼接——内核对此的对策是 seq_file 的 <code>stop</code>/重启机制（检测到不一致时重读），应用侧则应避免把 /proc 输出当作严格一致的事务快照。</p><h2 id="sysfs-的对象模型-kobject-与-kset" tabindex="-1">sysfs 的对象模型：kobject 与 kset <a class="header-anchor" href="#sysfs-的对象模型-kobject-与-kset" aria-label="Permalink to “sysfs 的对象模型：kobject 与 kset”">​</a></h2><p>sysfs 背后是 Linux 设备模型的核心抽象——<strong>kobject</strong>（kernel object）。kobject 是设备模型的最小单元：一个引用计数 + 一个名字 + 一个父指针 + 一个 ktype。它不直接代表&quot;设备&quot;——而是提供所有设备模型对象（device、driver、bus、class）的公共基础设施：引用计数生命周期、sysfs 目录表示、uevent 热插拔事件。</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kobject {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    const</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">      *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">       // sysfs 中的目录名</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list_head entry;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      // 挂入父 kset 的链表</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kobject   </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parent;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    // 父目录（层级结构）</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kset      </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kset;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      // 所属的 kset</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kobj_type </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ktype;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     // 属性和释放回调</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kref      kref;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">       // 引用计数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p><strong>kset</strong> 是 kobject 的集合——它自身也内嵌一个 kobject（既当容器又当成员）。kset 的价值是分组和事件聚合：<code>/sys/block/</code> 下所有块设备的 kobject 属于同一个 kset，<code>/sys/devices/</code> 的设备层级通过 kset 组织。kset 还关联一个 <code>kset_uevent_ops</code>——决定这个集合的成员在什么条件下发出 add/remove/change 事件。</p><p>kobject 与 sysfs 目录的对应关系由 <code>kobject_add</code>（创建 sysfs 目录）和 <code>sysfs_create_file</code>（在目录下创建属性文件）建立。属性的读写最终落到 <code>kobj_type-&gt;sysfs_ops</code> 的 <code>show</code>/<code>store</code> 回调——这就是 <code>echo 1 &gt; /sys/class/leds/.../brightness</code> 的完整路径：sysfs 的 write → <code>sysfs_ops-&gt;store</code> → 驱动的处理函数。</p><p>设备模型各对象与 kobject 的关系是&quot;内嵌而非继承&quot;（C 语言无继承）：<code>struct device</code> 内嵌 <code>struct kdevice</code>……实际是 <code>device-&gt;kobj</code>，<code>device_driver</code>、<code>bus_type</code>、<code>class</code> 同样内嵌。对象生命周期由 kobject 的引用计数管理——<code>kobject_get</code>/<code>kobject_put</code>，计数归零时 <code>kobj_type-&gt;release</code> 回调销毁对象。这解决了设备模型最难的&quot;何时释放&quot;问题——热插拔场景下设备对象的最后一个引用者（可能是 sysfs 的一个打开文件）释放前对象不能消失。</p><p>用户态看到的 <code>/sys</code> 层级是 kobject 树的直接映射：<code>/sys/devices/pci0000:00/0000:00:1f.2/</code> 的目录深度对应设备在总线拓扑中的位置；<code>/sys/class/net/eth0</code> 是同一设备在&quot;class 视角&quot;下的符号链接——同一个 kobject，多个视角的呈现。理解&quot;kobject 是 sysfs 的骨骼&quot;之后，<code>/sys</code> 的目录结构不再是黑盒——它就是设备模型数据结构的文件系统投影。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};